onClick:
{{
  Declencher_Export_Paie.run()
    .then(() => {
      // On calcule le mois qu'on vient d'envoyer
      const moisCible = moment().date() >= 25 ? moment().format('YYYY-MM') : moment().subtract(1, 'months').format('YYYY-MM');
      // On le sauvegarde dans la mémoire du navigateur
      return storeValue('paie_envoyee_mois', moisCible);
    })
    .then(() => {
      showAlert('✅ Export envoyé ! Le module est masqué jusqu\'au mois prochain.', 'success');
    })
    .catch((err) => showAlert('❌ Erreur lors de l\'envoi : ' + err.message, 'error'));
}}
